children:
{isAdjustmentIncrease
                          ? CURRENCIES.map((currency) => (
                            <option key={currency.code} value={currency.code}>{currency.label}</option>
                          ))
                          : adjustmentCurrencies.map((currency) => (
                            <option key={currency} value={currency}>
                              {CURRENCIES.find((option) => option.code === currency)?.label ?? currency}
                            </option>
                          ))}

{!ri.producto_id ? <option value="">Sin vincular a inventario</option> : null}{products
                            .filter((product) => product.activo && product.unidad.trim() === (oi?.unit ?? "").trim())
                            .map((product) => (
                              <option key={product.id} value={product.id}>{product.nombre}</option>
                            ))}
